import{_ as e,a as o,o as d,a4 as r}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse('{"title":"Catalog mapping — products, categories, attributes","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/rest-graphql-mapping/shop/catalog.md","filePath":"api/rest-graphql-mapping/shop/catalog.md","lastUpdated":1784902076000}'),a={name:"api/rest-graphql-mapping/shop/catalog.md"};function c(s,t,i,u,p,l){return d(),o("div",null,t[0]||(t[0]=[r('<h1 id="catalog-mapping-—-products-categories-attributes" tabindex="-1">Catalog mapping — products, categories, attributes <a class="header-anchor" href="#catalog-mapping-—-products-categories-attributes" aria-label="Permalink to &quot;Catalog mapping — products, categories, attributes&quot;">​</a></h1><p>The catalog is where REST and GraphQL differ most. REST puts filters in the query string; GraphQL packs them into one JSON <code>filter:</code> string and uses typed <code>sortKey</code>/<code>reverse</code> + cursor arguments.</p><h2 id="products-—-filters" tabindex="-1">Products — filters <a class="header-anchor" href="#products-—-filters" aria-label="Permalink to &quot;Products — filters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>REST</th><th>GraphQL</th></tr></thead><tbody><tr><td>Full-text search</td><td><code>GET /api/shop/products?query=shirt</code></td><td><code>products(query: &quot;shirt&quot;)</code></td></tr><tr><td>Scope to a category</td><td><code>?category_id=N</code> (alias <code>?categoryId=N</code>)</td><td><code>filter: &quot;{\\&quot;category_id\\&quot;:\\&quot;N\\&quot;}&quot;</code></td></tr><tr><td>Price range</td><td><code>?price=10,200</code> — or <code>?price_from=10&amp;price_to=200</code></td><td><code>filter: &quot;{\\&quot;price\\&quot;:\\&quot;10,200\\&quot;}&quot;</code></td></tr><tr><td>New products</td><td><code>?new=1</code></td><td><code>filter: &quot;{\\&quot;new\\&quot;:1}&quot;</code></td></tr><tr><td>Featured products</td><td><code>?featured=1</code></td><td><code>filter: &quot;{\\&quot;featured\\&quot;:1}&quot;</code></td></tr><tr><td>Product type</td><td><code>?type=configurable</code></td><td><code>filter: &quot;{\\&quot;type\\&quot;:\\&quot;configurable\\&quot;}&quot;</code></td></tr><tr><td>Attribute facet (color/size/brand/…)</td><td><code>?color=3&amp;size=6</code> (or <code>?filter[color]=3</code>)</td><td><code>filter: &quot;{\\&quot;color\\&quot;:\\&quot;3\\&quot;,\\&quot;size\\&quot;:\\&quot;6\\&quot;}&quot;</code></td></tr><tr><td>Multiple option ids for one facet</td><td><code>?color=1,2,3</code></td><td><code>filter: &quot;{\\&quot;color\\&quot;:\\&quot;1,2,3\\&quot;}&quot;</code></td></tr></tbody></table><ul><li>The <code>price</code> value is <code>&quot;{min},{max}&quot;</code> — the comma splits min from max, <strong>not</strong> a thousands separator (<code>?price=10,200</code> = min 10, max 200).</li><li>Any key that isn&#39;t reserved is a filterable attribute — new attributes (<code>material</code>, <code>pattern</code>, …) work with no schema change on either transport.</li><li>Discover filterable attributes + option ids from <a href="/api/rest-api/shop/attributes/get-attributes.html">Get Attributes</a> (<code>isFilterable: 1</code>).</li></ul><h2 id="products-—-sort-pagination" tabindex="-1">Products — sort &amp; pagination <a class="header-anchor" href="#products-—-sort-pagination" aria-label="Permalink to &quot;Products — sort &amp; pagination&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>REST</th><th>GraphQL</th></tr></thead><tbody><tr><td>Sort</td><td><code>?sort=price-asc</code> (or <code>?sort=price&amp;order=asc</code>)</td><td><code>sortKey: &quot;PRICE&quot;, reverse: false</code></td></tr><tr><td>Sort — newest</td><td><code>?sort=created_at-desc</code></td><td><code>sortKey: &quot;CREATED_AT&quot;, reverse: true</code></td></tr><tr><td>Sort — name</td><td><code>?sort=name-asc</code></td><td><code>sortKey: &quot;TITLE&quot;, reverse: false</code></td></tr><tr><td>Page size</td><td><code>?per_page=30</code> (max 50)</td><td><code>first: 30</code></td></tr><tr><td>Next page</td><td><code>?page=2</code></td><td><code>after: &quot;&lt;endCursor&gt;&quot;</code></td></tr><tr><td>Total count</td><td><code>X-Total-Count</code> response header</td><td><code>pageInfo</code> / <code>totalCount</code></td></tr></tbody></table><p>Full parameter and sort-token list: <a href="/api/rest-api/shop/products/search-product.html">Search Products (REST)</a> · <a href="/api/graphql-api/shop/queries/search-products.html">Search Products (GraphQL)</a>.</p><h2 id="products-—-read" tabindex="-1">Products — read <a class="header-anchor" href="#products-—-read" aria-label="Permalink to &quot;Products — read&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>REST</th><th>GraphQL</th></tr></thead><tbody><tr><td>List / search</td><td><code>GET /api/shop/products</code></td><td><code>products</code></td></tr><tr><td>Single product (by id)</td><td><code>GET /api/shop/products/{id}</code></td><td><code>product(id: N)</code></td></tr><tr><td>Single product (by url_key)</td><td>—</td><td><code>product(urlKey: &quot;slug&quot;)</code> — cross-locale lookup, GraphQL only</td></tr></tbody></table><h2 id="categories" tabindex="-1">Categories <a class="header-anchor" href="#categories" aria-label="Permalink to &quot;Categories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>REST</th><th>GraphQL</th></tr></thead><tbody><tr><td>Flat list</td><td><code>GET /api/shop/categories</code></td><td><code>categories</code> (cursor)</td></tr><tr><td><strong>Children of a category</strong></td><td><code>?parent_id=N</code> (alias <code>?parentId=N</code>)</td><td><code>treeCategories(parentId: N)</code> — <strong>not</strong> <code>categories</code>; the <code>categories</code> field has <strong>no</strong> <code>parentId</code> argument</td></tr><tr><td>Nested tree</td><td><code>GET /api/shop/category-trees</code></td><td><code>treeCategories(parentId: N)</code> — omit <code>parentId</code> for roots</td></tr><tr><td>Single category</td><td><code>GET /api/shop/categories/{id}</code></td><td><code>category(id: N)</code></td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">The #1 catalog mismatch</p><p><code>categories(parentId:)</code> does <strong>not</strong> exist. To get a category&#39;s children, use <code>treeCategories(parentId: N)</code> in GraphQL, or <code>?parent_id=N</code> in REST. Both list endpoints only return active (status = 1) categories.</p></div><h2 id="attributes" tabindex="-1">Attributes <a class="header-anchor" href="#attributes" aria-label="Permalink to &quot;Attributes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>REST</th><th>GraphQL</th></tr></thead><tbody><tr><td>List attributes</td><td><code>GET /api/shop/attributes</code></td><td><code>attributes</code></td></tr><tr><td>Attribute options</td><td><code>GET /api/shop/attribute-options</code></td><td><code>attributeOptions</code></td></tr></tbody></table><p>Attributes are the source for the facet filter sidebar — read them to learn which filter keys and option ids the product filters above accept.</p>',16)]))}const g=e(a,[["render",c]]);export{h as __pageData,g as default};
